sources['io/tvos/WeatherTest.java']='''package io.tvos;import io.tvos.setup.SetupState;import android.app.AlertDialog;import java.util.*;class WeatherTest extends android.content.Context {boolean active=true,transitioning;int page=SetupState.WEATHER,advances,cancels;Object request;AutoRegion.Result detectedCity;String weatherStatus="";AlertDialog cityDialog;final SettingsCitySearch citySearch=new SettingsCitySearch();final SetupFinishView finishView=new SetupFinishView();String text(int id){return "text"+id;}void next(){advances++;page=SetupState.TV;}void cancelWork(){cancels++;}void task(java.util.concurrent.Callable<Runnable> work){try{work.call().run();}catch(Exception e){throw new AssertionError(e);}}
'''+methods+'''
static void check(boolean b,String s){if(!b)throw new AssertionError(s);}public static void main(String[] args){WeatherTest auto=new WeatherTest();auto.detectWeather();check(auto.finishView.label.equals("Chisinau")&&Prefs.writes==0&&auto.advances==0,"auto detection previews without changing city");check(ApkTransfer.url.contains("city,latitude,longitude")&&ApkTransfer.url.contains("lang=ru"),"full location and current language requested");auto.citySearch.message="No results";auto.updateWeatherText();check(auto.finishView.label.equals("Chisinau")&&auto.finishView.status.equals("No results"),"manual error never replaces the detected-city button label");auto.chooseDetectedCity();check(Prefs.writes==1&&!Prefs.automatic&&Prefs.city.equals("Chisinau")&&auto.advances==1&&HomeData.refreshes==1,"explicit detected-city choice saves coordinates, exits automatic mode and advances once");auto.chooseDetectedCity();check(Prefs.writes==1,"late repeat from departed page ignored");
WeatherTest manual=new WeatherTest();manual.askCity();check(manual.cityDialog.isShowing(),"manual opens shared city dialog");SettingsCityDialog.submit.accept("  ");check(manual.citySearch.query==null&&manual.cancels==0,"blank input does not cancel automatic lookup");SettingsCityDialog.submit.accept("Balti");check(manual.citySearch.query.equals("Balti")&&manual.cancels==1,"manual query uses shared search and cancels competing location lookup");List<String[]> result=new ArrayList<>();result.add(new String[]{"Balti, Moldova","Balti","47.7","27.9","123","ru"});manual.showCityResults(result);result.clear();manual.cityDialog.click.run(manual.cityDialog,0);check(Prefs.city.equals("Balti")&&Prefs.id==123&&manual.advances==1,"snapshotted city result saves actual ID and coordinates");
WeatherTest stale=new WeatherTest();stale.showCityResults(Arrays.<String[]>asList(new String[]{"X","X","0","0","0","en"}));stale.active=false;stale.cityDialog.click.run(stale.cityDialog,0);check(Prefs.writes==2,"paused dialog never writes city");
WeatherTest vpn=new WeatherTest();NetworkStatus.vpn=true;int calls=ApkTransfer.calls;vpn.detectWeather();check(ApkTransfer.calls==calls&&vpn.detectedCity==null&&vpn.finishView.label.equals(vpn.text(R.string.settings_setup_city_failed)),"VPN does not get disabled or silently used for automatic location");NetworkStatus.vpn=false;ApkTransfer.body="bad";vpn.detectWeather();check(vpn.detectedCity==null&&vpn.advances==0,"malformed location remains recoverable");vpn.citySearch.message="No results";vpn.updateWeatherText();check(vpn.finishView.status.equals("No results"),"manual search error is visible");System.out.println("PASS: actual setup city detection, explicit save, manual search/results, stale guards, VPN policy and recoverable failures");}}
'''
with tempfile.TemporaryDirectory() as tmp:
 root=Path(tmp)
 for name,text in sources.items():
  p=root/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text)
 subprocess.run(['java','com.sun.tools.javac.Main','--release','8','-Xlint:all,-options','-Werror','-d',tmp,*map(str,root.rglob('*.java'))],check=True)
 subprocess.run(['java','-cp',tmp,'io.tvos.WeatherTest'],check=True,timeout=15)
